contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: try to collect _am after optionally depositing _dep; assert the relationship
    function run(uint _dep, uint _am) public payable {
        // ensure this contract can send _dep when depositing
        if (_dep > 0) require(address(this).balance >= _dep);

        // Step 1: deposit _dep into c from this contract (if any)
        if (_dep > 0) {
            c.Deposit{value: _dep}();
        }

        // Read pre-state: balance recorded for this contract in c and contract ETH balance
        uint beforeRecorded = c.balances(address(this));
        uint beforeCbal = address(c).balance;

        // Try to call Collect(_am) and observe if it reverted
        bool reverted;
        try c.Collect(_am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read post-state
        uint afterRecorded = c.balances(address(this));
        uint afterCbal = address(c).balance;

        // General rule:
        // If Collect did not revert then:
        //  - the recorded balance decreased by exactly _am (or decreased by at least _am and not below zero as stored in unsigned)
        //  - the contract's ETH balance decreased by at least _am
        // We express this safely to avoid underflow in the assert by comparing sums.
        assert(
            reverted || (
                // recorded balance decreased by _am
                beforeRecorded >= afterRecorded && // no unexpected increase
                (beforeRecorded - afterRecorded) == _am &&
                // contract ETH balance decreased by at least _am
                beforeCbal >= afterCbal &&
                (beforeCbal - afterCbal) >= _am
            )
        );
    }

    // allow this test contract to receive ETH so it can call c.Deposit
    receive() external payable {}
}

