contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Run takes the amount to collect and a prior depositAmount to set up funds.
    // This function will: optionally deposit depositAmount into c from this contract,
    // then attempt Collect(amount) and assert the invariant described.
    function run(uint depositAmount, uint amount) public payable {
        // ensure we can send depositAmount when needed
        require(address(this).balance >= depositAmount);

        // initial observed values
        uint beforeContractBal = address(c).balance;
        uint beforeMyBal = c.balances(address(this));

        // If depositAmount>0, perform a deposit to ensure there are funds to collect from.
        if (depositAmount > 0) {
            // call Deposit with value
            c.Deposit{value: depositAmount}();
        }

        // record values after deposit
        uint midContractBal = address(c).balance;
        uint midMyBal = c.balances(address(this));

        // Attempt Collect(amount) and capture whether it reverted
        bool reverted;
        try c.Collect(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // values after collect attempt
        uint afterContractBal = address(c).balance;
        uint afterMyBal = c.balances(address(this));

        // General property:
        // - If Collect did not revert, then the caller's public balance decreased by exactly amount
        //   and the contract's balance decreased by exactly amount.
        // - If Collect reverted, neither the caller's public balance nor the contract balance changed.
        assert(
            (!reverted && midMyBal >= amount && midContractBal >= amount && afterMyBal + amount == midMyBal && afterContractBal + amount == midContractBal)
            || (reverted && afterMyBal == midMyBal && afterContractBal == midContractBal)
        );
    }

    // Allow this test contract to receive ether for funding deposits
    receive() external payable {}
}

